static NSDictionary *Catalog(NSString *name){NSString *path=[NSBundle.mainBundle pathForResource:name ofType:@"json" inDirectory:@"AIProviders"];NSString *test=NSProcessInfo.processInfo.environment[@"DYLIX_PROVIDER_RESOURCES"];if(test.length)path=[test stringByAppendingPathComponent:[name stringByAppendingString:@".json"]];id j=path?[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:path]?:NSData.data options:0 error:nil]:nil;return [j isKindOfClass:NSDictionary.class]&&[j[@"schemaVersion"] isEqual:@1]?j:@{};}
NSArray<NSDictionary *> *TFAIProviderRegistry(void){static NSArray *rows;static dispatch_once_t once;dispatch_once(&once,^{NSMutableArray *valid=[NSMutableArray new];NSMutableSet *ids=[NSMutableSet new];for(id row in Catalog(@"Providers")[@"providers"]){if(![row isKindOfClass:NSDictionary.class]||![row[@"id"] isKindOfClass:NSString.class]||[ids containsObject:row[@"id"]]||![@[@"chat",@"responses",@"anthropic",@"gemini"] containsObject:row[@"wireProtocol"]])continue;[valid addObject:row];[ids addObject:row[@"id"]];}rows=valid.copy;});return rows;}
NSDictionary *TFAIProvider(NSString *identifier){for(NSDictionary *p in TFAIProviderRegistry())if([p[@"id"] isEqual:identifier])return p;return @{};}
NSString *TFAIWireProtocol(NSString *identifier){return TFAIProvider(identifier)[@"wireProtocol"]?:identifier;}
NSArray<NSDictionary *> *TFAIFamilyReasoningOptions(NSDictionary *c){static NSDictionary *catalog;static dispatch_once_t once;dispatch_once(&once,^{catalog=Catalog(@"Thinking");});NSMutableArray *result=[NSMutableArray arrayWithObject:@{@"id":@"auto",@"name":DXLoc(@"默认")}];NSString *protocol=c[@"protocol"]?:@"chat",*model=[c[@"model"] lowercaseString]?:@"";model=model.lastPathComponent;for(NSDictionary *rule in catalog[@"rules"]){if(rule[@"protocols"]&&![rule[@"protocols"] containsObject:protocol])continue;if([model rangeOfString:rule[@"modelPattern"] options:NSRegularExpressionSearch].location==NSNotFound)continue;if(rule[@"excludePattern"]&&[model rangeOfString:rule[@"excludePattern"] options:NSRegularExpressionSearch].location!=NSNotFound)continue;for(NSString *level in rule[@"levels"])[result addObject:@{@"id":level,@"name":catalog[@"labels"][level]?:level}];break;}return result;}
NSDictionary *TFAIObservedCapabilities(NSDictionary *c){NSMutableDictionary *out=[NSMutableDictionary new];for(NSString *k in @[@"text",@"stream",@"image",@"tools",@"thinking"]){NSString *s=c[@"capabilities"][k];out[k]=[@[@"supported",@"unsupported"] containsObject:s]?s:@"unknown";}return out;}
NSString *TFAIConnectionCaption(NSDictionary *c){NSDictionary *caps=TFAIObservedCapabilities(c);NSMutableArray *verified=[NSMutableArray new];for(NSString *k in @[@"text",@"stream",@"image",@"tools"]){NSString *state=caps[k];if(![state isEqual:@"unknown"])[verified addObject:[NSString stringWithFormat:@"%@%@",@{@"text":DXLoc(@"文本"),@"stream":DXLoc(@"流式"),@"image":@"图片",@"tools":DXLoc(@"工具")}[k],[state isEqual:@"supported"]?@"✓":@"×"]];}return [NSString stringWithFormat:@"%@ · %@ · %@",TFAIProvider(c[@"protocol"])[@"name"]?:c[@"name"]?:DXLoc(@"未选服务商"),c[@"model"]?:DXLoc(@"未选模型"),verified.count?[[@"实测：" stringByAppendingString:[verified componentsJoinedByString:@"/"]] stringByAppendingString:@" · 其余unknown"]:DXLoc(@"能力 unknown")];}
